 let rows,total;
 if(me){const params=new URLSearchParams({limit:String(pageSize),offset:String(page*pageSize)});if(state.listQuery)params.set('q',state.listQuery);if(state.listState)params.set('state',state.listState);const result=await api('/positions?'+params);rows=result.items;total=result.total;}
 else{const parts=C.normalize(state.listQuery).split(' ').filter(Boolean),all=C.read(localStorage).filter(p=>(!state.listState||p.state===state.listState)&&parts.every(q=>C.normalize(p.title).includes(q)));total=all.length;rows=all.slice(page*pageSize,(page+1)*pageSize);}
